import{_ as i,l,o as e,c as s,v as r,p as d,x as t,d as n,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"硬烤与 UV 固化","description":"","frontmatter":{"title":"硬烤与 UV 固化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hard-bake-uv-cure.md","filePath":"litho/hard-bake-uv-cure.md","lastUpdated":1789023840000}'),p={name:"litho/hard-bake-uv-cure.md"};function u(E,a,_,m,B,f){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="硬烤与-uv-固化" tabindex="-1">硬烤与 UV 固化 <a class="header-anchor" href="#硬烤与-uv-固化" aria-label="Permalink to &quot;硬烤与 UV 固化&quot;">​</a></h1><div class="epigraph"><p>硬烤提高模量、赶尽溶剂，让胶扛得住开口等离子体；UV 固化走交联，热预算可以更低。</p><footer>—— 对照 post-develop hard bake / UV cure 在转印前的公开用途</footer></div><p><a href="/litho/descum">上一课</a>清完渣。缺口是膜还软：主刻蚀、真空、电子束量测都会流胶或放气。本课钉硬烤与 UV 固化，不写剥离灰化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软烤只为曝光。显影后聚合物网络更开、溶剂和显影液残余仍在。不硬化：刻蚀中流、倒塌阈值低、SEM 收缩（<a href="/litho/cd-sem-shrink">CD-SEM 收缩</a>）。烤太高：图形圆化、CD 涨、甚至裂。需要一条「转印前热/光」预算。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>热板硬烤：温度低于分解、高于软烤，时间分钟级。UV（宽带或 172 nm 一类，以设备公开能力为准）诱发交联，可降热。金属氧化物胶的硬化化学不同，不要套 CAR 的温度表。固化后再量 CD，才是给刻蚀的合同尺寸。</p>',7)),(e(),d(c,null,{default:t(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E6%98%BE%E5%BD%B1%E5%90%8E%E5%9B%BE%E5%BD%A2%22%5D%20--%3E%20HB%5B%22%E7%A1%AC%E7%83%A4%20%2F%20UV%22%5D%0A%20%20HB%20--%3E%20MOD%5B%22%E6%A8%A1%E9%87%8F%20%E2%86%91%20%E6%BA%B6%E5%89%82%20%E2%86%93%22%5D%0A%20%20MOD%20--%3E%20ETCH%5B%22%E5%BC%80%E5%8F%A3%20%2F%20%E4%B8%BB%E5%88%BB%E8%9A%80%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p><span class="marginnote">UV 固化对深层胶的穿透有限，厚 SOC 不能指望一次 UV 烤透。分层固化或只固化成像层。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>交联与致密化提高 \\(E\\)，毛细与等离子体下的变形变小。体积收缩改 CD 与应力。光酸若还在，高温会继续反应——与 PEB 不同，这是图形已形成后的二次反应，可能糊边。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课轨道–扫描仪联机：硬化在 track 上，曝光在 scanner 上，时间线要对上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬烤/UV 是转印前的力学与放气预算。</li><li>过热糊边；过低流胶。合同 CD 应在固化后量。</li><li>出处：hard bake / UV cure 工艺通识。</li></ul>',7))])}const b=i(p,[["render",u]]);export{A as __pageData,b as default};
